-- Généré par « npm run import -- --sql netlify/database/migrations/0002_seed_pat_et_lola.sql » à partir des fichiers de data/.
insert into principe (id, numero, titre, regle, tags, role, statut, version_ajout, principes_lies) values ('points-ancrage', '1', 'Les points d''ancrage', 'Pour construire un accord, identifier 1 à 3 éléments du plat (texture, sauce, épice, condiment, herbe, saveur dominante) sur lesquels accrocher le vin. Le vin n''épouse jamais le plat dans sa totalité, mais via ses points d''ancrage.', '{"methode","fondamental"}', 'methode', 'valide', 'V3', '{}'), ('resonance-sols', '2', 'La résonance des sols et des terroirs', 'Un vin du même environnement géographique que le plat (même région, même type de sol) marche souvent mieux qu''un grand vin prestigieux d''ailleurs. Le cochon broute la végétation que la vigne respire — d''où Gamay du Valais sur charcuterie suisse, Grenache du Rhône Sud sur daube provençale.', '{"methode","geographie","terroir"}', 'methode', 'valide', 'V3', '{}'), ('echanges-acide-gras', '3', 'Acidité ↔ gras', 'L''acidité du vin coupe le gras du plat ; inversement, un plat gras adoucit la perception d''acidité du vin. Règle centrale pour tout plat à matière grasse (saumon fumé, foie gras, fromages crémeux).', '{"interaction","saveur"}', 'interaction', 'valide', 'V3', '{}'), ('echanges-sucre-sel', '4', 'Sucre ↔ sel : l''accord d''opposition classique', 'Le sucre du vin neutralise le sel du plat et vice-versa. Archétypes : Roquefort + Sauternes, Munster + Gewurz VT, foie gras au sel + Jurançon moelleux. C''est l''accord d''opposition le moins risqué — bien maîtriser avant les opposés plus complexes (amer/acide, amer/sucre).', '{"opposition","fromage","doux"}', 'interaction', 'valide', 'V3', '{}'), ('echanges-tanin-fromage', '5', 'Le fromage repousse de facto le tanin', 'Sur tous les fromages, éviter les rouges jeunes tanniques. Préférer rouge évolué peu coloré (Poulsard, Trousseau patiné), blanc tendu, ou vin doux selon le type (sucré sur bleu, blanc sur pâte pressée locale).', '{"fromage","tanin"}', 'exclusion', 'valide', 'V3', '{}'), ('epices-rouges-jeunes', '6', 'Plats épicés ↔ jamais de rouge jeune tannique', 'Le piment, les épices fortes durcissent les tanins jeunes — l''accord vire métallique, abrasif. Sur curry, plats indiens/thaï/tex-mex/mexicains : blanc tendu en acidité, ou moelleux équilibré (le sucre enveloppe la chaleur). Les rouges si on y tient : sur sols frais (altitude, schistes, exposition nord) qui apportent de la fraîcheur au vin.', '{"epices","piment","tanin"}', 'exclusion', 'valide', 'V3', '{}'), ('agrumes-incompatibles-seuls', '7', 'Agrumes seuls = incompatibles, agrumes adoucis = possibles', 'Le citron, le pamplemousse, les agrumes nature sont incompatibles avec le vin (acidité agressive). Mais en dessert sucré (tarte au citron, fruits de la passion), le sucre adoucit l''agrume — un effervescent sucré-acidulé peu alcoolisé (Clairette de Die, Cerdon) crée alors un accord étincelant.', '{"agrumes","doux","effervescent","dessert"}', 'exclusion', 'valide', 'V3', '{}'), ('asperge-pas-refractaire', '8', 'L''asperge n''est pas si réfractaire — point d''ancrage : terre + végétal', 'L''asperge n''est pas l''ennemie du vin. Son vrai point d''ancrage est sa nature terreuse et végétale, pas son amertume. Cépages aromatiques au profil terreux (muscat, chasselas vieilles vignes, aligoté patiné de 4-6 ans, viognier pour ses amers) ou pinot noir septentrional finement végétal.', '{"asperge","refractaire","blanc","vegetal"}', 'interaction', 'valide', 'V3', '{}'), ('anchois-acidite-salinite', '9', 'Anchois et iodés salins ↔ acidité littorale', 'L''anchois (et la salinité concentrée en général) appelle des blancs nerveux et tranchants en acidité, idéalement de sols proches de la mer ou des fleuves : exemple: Muscadet, Chablis, Cassis. Effervescents cohérents : Champagne, Vouvray, Saumur. La proximité géographique avec l''eau est protectrice.', '{"anchois","iode","salinite","blanc"}', 'interaction', 'valide', 'V3', '{}'), ('oeufs-difficiles-sauf-meurette', '10', 'Œufs : difficiles partout, sauf l''œuf en meurette', 'La texture des œufs (durs, mayonnaise, omelette, brouillés) déstabilise le vin. Exception majeure : l''œuf en meurette — la sauce au vin rouge devient le point d''ancrage et appelle un rouge souple et juteux qui prolonge la réduction.', '{"oeufs","refractaire","meurette"}', 'plafond', 'valide', 'V3', '{}'), ('vinaigrette-moutarde-incompatibles', '11', 'Vinaigrette et moutarde franche ↔ incompatibles avec le vin', 'Le piquant vinaigré déstabilise les rouges comme les blancs : pas d''accord viable. Si vinaigrette inévitable, en réduire la part dans le plat ou opter pour un vin tendu très acide qui partage le terrain (un blanc nerveux, un effervescent extra-brut).', '{"vinaigrette","moutarde","refractaire"}', 'exclusion', 'valide', 'V3', '{}'), ('soupe-pas-eau-obligee', '12', 'Avec les soupes on peut boire du vin (mais subtilement)', 'L''idée scolaire « avec les soupes on boit de l''eau » est obsolète. L''onctuosité étouffe certes le vin, mais un blanc désaltérant et tendu peut tenir. À éviter : tout vin riche qui doublerait la consistance.', '{"soupe","veloute","blanc-tendu"}', 'interaction', 'valide', 'V3', '{}'), ('poivre-viande', '13', 'Poivre + viande ↔ tanins fondus et trame acide', 'Sur foie gras poêlé + poivre, ou bœuf au poivre, ou tout plat où le poivre marque, un vin rouge avec des tanins fondus et une trame acide crée la passerelle entre la texture grasse et le piquant épicé (exemple: vieux grand cru bourguignon).', '{"poivre","bourgogne","mature"}', 'interaction', 'valide', 'V3', '{}'), ('caramélisé-alcool', '14', 'notes caramélisées - richesse alcoolique', 'Quand une cuisson donne des notes caramélisées : un vin avec une richesse alcoolique permet de développer ces notes.', '{"notes caramélisées"}', 'interaction', 'valide', 'V3', '{}'), ('chocolat-amer-vdn', '15', 'Chocolat noir ↔ VDN par opposition', 'Le chocolat noir relève des accords d''opposition réussis. VDN muté (exemple: Maury, Banyuls) : amertume cacao contre amertume noix, sucre du vin compensant la charge cacaotée. La mousse au chocolat reste l''accord parfait le plus difficile — le vin doit garder sa fraîcheur sans se faire écraser.', '{"chocolat","vdn","maury","banyuls","opposition"}', 'interaction', 'valide', 'V3', '{}'), ('ordre-service-progression', '16', 'Ordre de service : du plus tendu vers le plus puissant, du sec vers le doux', 'Commencer un repas par les bulles ou un blanc tendu et léger ; monter en puissance ; finir par le sucre (dessert). Ne jamais redescendre en intensité ou retourner au sec après le sucré — l''amour-propre du vin précédent se brouille.', '{"méthode","service","ordre","menu"}', 'methode', 'valide', 'V3', '{}'), ('opposition-debutants', '17', 'Accords d''opposition : commencer par sucre/sel', 'L''opposition la moins risquée est sucre/sel (Roquefort + Sauternes, Munster + Gewurz VT). Plus délicates : amer/acide, amer/sucre. Maîtriser le sucre/sel d''abord, puis explorer.', '{"opposition","debutant","doux"}', 'methode', 'valide', 'V3', '{}'), ('vin-transversal-plusieurs-plats', '18', 'Un vin pour plusieurs plats : partir du plat le plus fragile', 'Quand on a plusieurs plats avec un vin, on ne cherche pas le vin idéal de chaque plat, mais le vin qui ne se brise sur aucun. On identifie d''abord ce que le plat le plus délicat ne supporte pas (pour un poisson, un tanin appuyé), puis un point d''ancrage commun aux deux plats (une sauce, une cuisson grillée, une herbe).', '{"methode","compromis","plusieurs plats différents"}', 'methode', 'valide', 'V3', '{}'), ('bois-couvre-finesse', '19', 'Le bois couvre la finesse et amplifie l''amertume', 'Un vin boisé (fût neuf, notes vanillées, toastées) couvre les saveurs délicates et amplifie l''amertume du plat. Sur poisson cru, asperge, burrata, chèvre, crustacés fins : blanc sans bois ou très peu boisé. Le bois n''a sa place que sur des plats riches (volaille crémée, viandes rôties) capables de lui répondre.', '{"bois","finesse","amertume","blanc"}', 'interaction', 'valide', 'V3', '{}'), ('equilibre-intensite', '20', 'L''équilibre des intensités : le vin pèse autant que le plat', 'Un plat léger avec un vin léger, un plat riche avec un vin structuré. Un vin trop riche est écrasé par le sel ou double l''onctuosité du plat ; un vin trop léger disparaît derrière un plat puissant. Avant tout autre critère, peser le plat et le vin sur la même balance.', '{"methode","intensite","equilibre"}', 'methode', 'valide', 'V3', '{}'), ('tanin-aime-gras-saignant', '21', 'Le tanin aime le gras et le saignant de la viande rouge', 'Pendant du principe « le fromage repousse le tanin » : les protéines, le gras et le sang d''une viande rouge saignante ou grillée lissent les tanins et rendent le vin plus souple et plus fruité. Entrecôte, côte de bœuf, magret rosé, gigot : c''est là que le rouge structuré est à sa place. Une viande maigre ou très cuite demande au contraire des tanins plus fins.', '{"tanin","viande-rouge","gras"}', 'interaction', 'valide', 'V3', '{}'), ('sucre-plat-vin-plus-sucre', '22', 'Le sucre du plat impose un vin au moins aussi sucré', 'Le sucre dans le plat (sauce à l''orange, miel, purée de pommes, glaçage, fruits) augmente la perception de l''amertume, de l''acidité et de l''alcool du vin, et lui retire son fruit. Un rouge tannique jeune se durcit, un sec paraît maigre. Règle : le vin doit avoir au moins autant de sucre que le plat. Distinct de « sucre ↔ sel », qui traite du sucre du vin contre le sel du plat.', '{"sucre","doux","tanin","sauce"}', 'interaction', 'valide', 'V3', '{}'), ('acidite-plat-acidite-vin', '23', 'L''acidité du plat impose l''acidité du vin', 'Un vin moins acide que le plat paraît plat et mou. Tomate cuite, câpres, citron, vinaigre, cornichons : choisir un vin d''acidité au moins égale. Un rouge tannique sur la tomate vire au métallique. Le principe « vinaigrette ↔ incompatible » en est le cas extrême.', '{"acidite","tomate","vinaigre"}', 'interaction', 'valide', 'V3', '{}'), ('sauce-cuisson-priment', '24', 'La sauce et la cuisson priment sur la protéine', 'Le même produit change de vin selon la sauce et la cuisson : cabillaud beurre blanc et cabillaud plancha, filet nature et filet au poivre ne s''accordent pas de la même façon. La sauce est le premier point d''ancrage, la cuisson le second : grillé et caramélisé appellent fruit noir et épices ; braisé et mijoté appellent un vin évolué ; vapeur et cru appellent un blanc tendu.', '{"methode","sauce","cuisson","ancrage"}', 'methode', 'valide', 'V3', '{}'), ('accord-miroir', '25', 'L''accord de miroir : faire résonner un arôme commun', 'Pendant des accords d''opposition : chercher un arôme partagé entre le vin et le plat. Viande fumée de la syrah sur le pigeon ou le gibier, buis et agrumes du sauvignon sur le citron du tartare, notes tertiaires (sous-bois, cuir) d''un vin évolué sur la truffe et les champignons, garrigue du grenache sur les herbes de Provence. Deux familles d''accords : miroir (complémentarité) et opposition (contraste).', '{"methode","miroir","resonance","aromes"}', 'methode', 'valide', 'V3', '{}'), ('temperature-service', '26', 'La température de service modifie l''accord', 'Un rouge servi trop chaud accentue l''alcool et le tanin ; un blanc glacé perd ses arômes et son gras. Repères : effervescents et blancs tendus 8-10 °C, blancs riches 11-12 °C, rouges légers 13-14 °C, rouges structurés 16-17 °C. Un rouge léger servi frais devient le vin de passage entre poisson et viande.', '{"service","temperature","pratique"}', 'service', 'valide', 'V3', '{}'), ('rouge-sur-poisson', '27', 'Rouge et poisson : possible si le poisson est charnu et le rouge peu tannique', 'Le rouge n''est pas exclu sur le poisson. Sur un poisson charnu grillé ou rôti (thon, saumon, bar, poissons gras), un rouge léger, peu tannique et servi frais (pinot noir, Beaujolais cru, Poulsard) tient. Le tanin appuyé sur la chair iodée donne un goût métallique : c''est lui qu''il faut éviter, pas la couleur. Complément de « vin transversal ».', '{"poisson","rouge","tanin"}', 'interaction', 'valide', 'V3', '{}'), ('sel-adoucit-vin', '28', 'Le sel adoucit le vin', 'Le sel (et l''acidité) du plat atténue la perception des tanins et de l''acidité du vin, qui paraît plus fruité, plus rond, plus souple. Une viande salée et grasse lisse un rouge tannique ; charcuterie, parmesan, jambon cru supportent des rouges plus structurés qu''on ne le croit. Pendant de « sucre ↔ sel » : sel ↔ tanin.', '{"sel","tanin","interaction"}', 'interaction', 'valide', 'V3', '{}'), ('umami-durcit-vin', '29', 'L''umami durcit le vin', 'Les aliments riches en umami (champignons, fromages affinés, œufs, asperges, sauce soja, viande longuement cuite) accentuent le tanin, l''amertume et l''acidité du vin et lui retirent son fruit. C''est la cause commune des « réfractaires » (asperge, œufs, fromage). Correctifs : saler le plat, choisir un vin évolué aux tanins fondus ou un blanc rond, éviter le rouge jeune tannique.', '{"umami","refractaire","tanin"}', 'interaction', 'valide', 'V3', '{}'), ('amertume-additionne', '30', 'L''amertume du plat s''additionne à celle du vin', 'Les aliments amers (chicon/endive, roquette, chicorée, artichaut, chou-fleur, brocoli, certaines épices comme la cardamome ou le gingembre) rendent désagréable un vin amer ou tannique. Préférer un blanc, ou un rouge peu tannique (cabernet franc, pinot noir, barbera). Le sucre du vin ou du plat (chicon braisé caramélisé) atténue l''amertume.', '{"amertume","legumes","tanin"}', 'interaction', 'valide', 'V3', '{}'), ('alcool-attise-piment', '31', 'L''alcool attise le piment', 'Complément de « plats épicés ↔ jamais de rouge jeune tannique » : l''alcool amplifie la chaleur du piment autant que le tanin. Sur un plat pimenté, un vin peu alcoolisé (11-12,5 %) et légèrement doux (Riesling Spätlese, Gewurztraminer, Vouvray demi-sec) enveloppe la chaleur ; un rouge puissant à 15 % la brûle.', '{"epices","piment","alcool"}', 'interaction', 'valide', 'V3', '{}'), ('grand-vin-se-suffit', '32', 'Un grand vin se suffit à lui-même : le plat s''adapte au vin', 'Sur une grande ou vieille bouteille, inverser le raisonnement : c''est le plat qui s''adapte au vin. Préparation simple, sans sauce forte ni épices, qui laisse le vin s''exprimer (volaille rôtie, viande blanche, champignons, châtaignes sur un vieux rouge). Les très grands vins s''apprécient en petit comité.', '{"methode","grand-vin","vieux-vin"}', 'methode', 'valide', 'V3', '{}'), ('saison-contexte', '33', 'La saison et le contexte pèsent sur l''accord', 'Les rouges corsés et généreux se goûtent mieux en hiver ; par forte chaleur, des vins frais et légers. Tenir compte aussi des convives, de l''occasion et du budget : un accord réussi n''est pas synonyme de vin cher. Un seul impératif, le plaisir doit aller crescendo.', '{"contexte","saison","convives"}', 'methode', 'valide', 'V3', '{}'), ('friture-bulles', '34', 'La friture appelle la bulle et l''acidité', 'La friture (croquettes, beignets, fish and chips, tempura) tapisse la bouche d''un gras chaud et croustillant. Un effervescent sec de méthode traditionnelle ou un blanc très tendu nettoie le palais à chaque gorgée : la bulle ajoute un effet mécanique à l''acidité. À éviter : rouge tannique (amer sur la panure), blanc boisé ou rond qui double le gras. Cas particulier de « Acidité ↔ gras ».', '{"friture","effervescent","acidite","gras"}', 'interaction', 'propose', 'V4', '{}'), ('plafond-refractaire', '35', 'Un élément réfractaire plafonne l''accord', 'Quand le plat contient un réfractaire (œuf en émulsion, vinaigrette, agrume nature, bleu sans vin doux disponible), aucun vin ne fait un accord parfait : on cherche le vin qui en souffre le moins et on l''annonce comme tel. Mieux vaut un accord « correct » assumé qu''un accord parfait promis. Correctifs côté cuisine : sauce servie à part, part réduite.', '{"methode","refractaire","honnetete"}', 'plafond', 'propose', 'V4', '{}'), ('garnitures-neutres', '36', 'Les garnitures neutres ne sont pas des points d''ancrage', 'Frites, pain, riz, pâtes nature, salade verte d''accompagnement pèsent peu dans l''accord : on ancre sur la protéine, la sauce et la cuisson. Exception : la vinaigrette de la salade d''accompagnement, qui peut ruiner un grand rouge — la servir à part ou légère. Complète « Les points d''ancrage ».', '{"methode","ancrage","garniture"}', 'methode', 'propose', 'V4', '{}'), ('fromage-accessoire', '37', 'Le fromage accessoire ne dicte pas seul l''accord', 'Quand le fromage n''est qu''une composante minoritaire d''un plat de viande (tranche fondue dans un burger, parmesan râpé sur des pâtes), le sel et la viande assouplissent le tanin : on évite seulement le rouge très jeune et très tannique, un rouge juteux aux tanins souples convient. Quand le fromage est l''ingrédient principal (croquette, croque, fondue, plateau), « Le fromage repousse de facto le tanin » s''applique pleinement. Nuance proposée au principe original n°5, qui vise « tous les fromages ».', '{"fromage","tanin","nuance"}', 'methode', 'propose', 'V4', '{}'), ('bleu-en-sauce-viande', '38', 'Sauce au bleu sur viande : le rouge le plus mûr, faute de vin doux', 'Sur une sauce au bleu (gorgonzola, roquefort) nappant une viande rouge, l''opposition sucre ↔ sel est hors de propos (un vin doux sur une viande). Choisir le rouge le plus mûr et le plus arrondi disponible (grenache, zinfandel, raisins passerillés type ripasso ou amarone), tanins souples ; éviter le rouge jeune et austère que le bleu durcit. Complète « Sucre ↔ sel » et « Le fromage repousse de facto le tanin ».', '{"fromage","bleu","sauce","viande-rouge"}', 'interaction', 'propose', 'V4', '{}'), ('elevage-lies-sans-bois', '39', 'L''élevage sur lies donne de la chair sans le bois', 'Un blanc élevé sur lies fines (bâtonnage) gagne gras et volume sans notes boisées. C''est l''outil des plats crémés ou de poids moyen (pâtes à la crème, volaille à la crème, poisson au beurre blanc) : l''acidité coupe la crème, la chair répond au poids du plat, sans que le bois couvre la finesse. Complète « Le bois couvre la finesse » et « L''équilibre des intensités ».', '{"blanc","elevage","lies","creme"}', 'interaction', 'propose', 'V4', '{}'), ('age-vin-oriente-plat', '40', 'L''âge du vin oriente le plat', 'Un vin jeune apporte fruit et tanin : il cherche le grillé, le gras, le saignant. Un vin évolué a des tanins fondus et des notes tertiaires (sous-bois, cuir, champignon) : il cherche les sauces aux champignons, les viandes maigres et simples, les braisés. Un grand vin servi trop jeune sur un plat délicat montre ses tanins. Relie « Poivre + viande », « L''accord de miroir », « L''umami durcit le vin » et « Un grand vin se suffit à lui-même ».', '{"evolution","vieux-vin","tanin","methode"}', 'methode', 'propose', 'V4', '{}'), ('effervescent-cepage-dosage', '41', 'Effervescents : le cépage et le dosage dictent la table', 'Un blanc de blancs (chardonnay) ou un cava tendu va aux iodés, aux fritures et à l''apéritif ; un champagne à dominante meunier ou pinot noir, plus vineux, tient la volaille, la crème et les plats de brasserie. Le dosage compte : brut nature ou extra-brut sur les sauces acides ou vinaigrées, brut sur la friture. Complète « Anchois et iodés salins ↔ acidité littorale ».', '{"effervescent","champagne","dosage","cepage"}', 'methode', 'propose', 'V4', '{}'), ('resonance-climat', '42', 'Sans vin du terroir du plat, chercher le même climat', 'Quand la carte n''a aucun vin de la région du plat (cuisine belge, britannique, nordique), la résonance des sols se transpose en résonance de climat : vins septentrionaux, frais et tendus (Loire, Champagne, Alsace, Moselle) pour une cuisine de mer du Nord ; vins solaires pour une cuisine méditerranéenne. Complète « La résonance des sols et des terroirs ».', '{"terroir","climat","geographie"}', 'methode', 'propose', 'V4', '{}'), ('aeration-avant-accord', '43', 'Aérer le rouge jeune avant de juger l''accord', 'Un rouge jeune et structuré servi sans aération paraît plus tannique et plus fermé : l''accord se juge après carafage (1 à 2 h selon la structure). Un vin évolué se décante brièvement, surtout pour séparer le dépôt, sans l''exposer trop longtemps à l''air. Complète « La température de service modifie l''accord ».', '{"service","carafe","aeration","pratique"}', 'service', 'propose', 'V4', '{}'), ('sauce-a-part-condiment', '44', 'Une sauce servie à part comme condiment ne dicte pas l''accord', 'Quand une sauce est servie à part et joue un rôle de condiment (on y trempe, ou on en assaisonne à sa guise : aigre-douce des nems, tartare d''une friture, vinaigre à l''échalote des huîtres), on accorde le vin au plat sans la sauce. Les points d''ancrage sont la cuisson, la texture, le produit et les garnitures (n°1). La sauce ne plafonne pas l''accord (n°35) et n''impose pas ses propres contraintes : ni un vin aussi sucré qu''elle (n°22), ni la réserve sur les émulsions (n°10) ou le vinaigre (n°11). On le signale au convive : utilisée avec parcimonie, la sauce laisse le vin intact ; utilisée largement, elle le fera paraître plus sec, plus acide ou plus dur. Ce principe ne s''applique pas à une sauce choisie comme composante du plat, même servie en saucière (le filet sauce morilles ou sauce béarnaise) : elle reste le point d''ancrage principal (n°24). Le service réel de chaque sauce se vérifie auprès du restaurant.', '{"methode","sauce","condiment","refractaire","honnetete"}', 'methode', 'propose', 'V5', '{"points-ancrage","oeufs-difficiles-sauf-meurette","vinaigrette-moutarde-incompatibles","sucre-plat-vin-plus-sucre","sauce-cuisson-priment","plafond-refractaire"}') on conflict (id) do update set numero = excluded.numero, titre = excluded.titre, regle = excluded.regle, tags = excluded.tags, role = excluded.role, statut = excluded.statut, version_ajout = excluded.version_ajout, principes_lies = excluded.principes_lies;
insert into question_pat (numero, question, principes) values ('1', 'Le n°5 vise « tous les fromages » : s''applique-t-il aussi quand le fromage est minoritaire (burger, parmesan sur des pâtes) ? Si oui, la proposition n°37 est à rejeter.', '{"echanges-tanin-fromage","fromage-accessoire"}'), ('2', 'Les n°4 (Sucre ↔ sel) et n°17 (Accords d''opposition : commencer par sucre/sel) se recoupent largement : les fusionner ?', '{"echanges-sucre-sel","opposition-debutants"}'), ('3', 'Le n°9 valorise les sols « proches de la mer ou des fleuves » : un Sancerre, sur les coteaux dominant la Loire, entre-t-il dans ce cas ?', '{"anchois-acidite-salinite"}'), ('4', 'Le n°10 (œufs) s''applique-t-il avec la même force aux émulsions (sauce César, béarnaise, mayonnaise) qu''à l''œuf entier ?', '{"oeufs-difficiles-sauf-meurette"}'), ('5', 'Le n°11 (vinaigrette) couvre-t-il les sauces acidulées au citron comme la sauce César, ou seulement la vinaigrette et la moutarde ?', '{"vinaigrette-moutarde-incompatibles"}'), ('6', 'Priorité de validation : les propositions n°20, 21, 23 et 24 fondent à elles seules plus de la moitié des notes de la matrice Bercuit. Les valider (ou corriger) en premier consoliderait l''analyse.', '{"equilibre-intensite","tanin-aime-gras-saignant","acidite-plat-acidite-vin","sauce-cuisson-priment"}'), ('7', 'Les n°6 et n°31 (épices et alcool) se complètent : les regrouper en un seul principe ?', '{"epices-rouges-jeunes","alcool-attise-piment"}'), ('8', 'Service des sauces à confirmer avec le restaurant : aigre-douce des nems, tartare des scampis, vinaigre à l''échalote des huîtres (servis à part, en condiment ?) et sauces du filet pur (saucière ou nappées ?). La réponse décide où s''applique le n°44.', '{"sauce-a-part-condiment"}') on conflict (numero) do update set question = excluded.question, principes = excluded.principes;
insert into terroir (id, ancien_id, nom, type, parent_id, pays, region, sous_region, cepages_rois, altitude_min, altitude_max, sols, caracteristiques, notes_objectives, niveau_reference, ranking_pat, avis_pat, tags, source) values ('bourgogne-terr-gc-bienvenues-batard', 'bgn-gc-bienvenues-batard', 'Bienvenues-Bâtard-Montrachet', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '240', '260', '{"Marnes argileuses"}', '3,7 ha. Le plus petit et le plus aérien des Bâtard. Carillon, Leflaive, Ramonet, Sauzet, Bachelard.', null, '5', '5', null, '{"puligny","chardonnay","finesse"}', 'lpv|inao'), ('bourgogne-terr-gc-batard-montrachet', 'bgn-gc-batard-montrachet', 'Bâtard-Montrachet', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '240', '260', '{"Marnes argileuses, sols profonds"}', '11,9 ha à cheval sur Puligny et Chassagne. Plus puissant et gras que Montrachet, parfois plus accessible jeune. Leflaive, Ramonet, Niellon, Pierre Morey, Drouhin.', null, '5', '5', null, '{"iconique","puligny","chassagne","chardonnay","puissance"}', 'lpv|inao'), ('bourgogne-terr-1c-montee-tonnerre', 'bgn-1c-montee-tonnerre', 'Chablis 1er Cru Montée de Tonnerre', 'premier_cru', null, 'France', 'Bourgogne', 'Chablis', '{"Chardonnay"}', '180', '220', '{"Calcaires kimméridgiens"}', '63,5 ha. Le plus grand et le plus prestigieux des 1ers crus de Chablis. Voisin direct des grands crus. Raveneau, William Fèvre, Drouhin, Pinson.', null, '5', '5', null, '{"chablis","premier-cru","grand-cru-de-fait"}', 'lpv|inao'), ('bourgogne-terr-gc-chablis-les-clos', 'bgn-gc-chablis-les-clos', 'Chablis Grand Cru Les Clos', 'climat', null, 'France', 'Bourgogne', 'Chablis', '{"Chardonnay"}', '180', '220', '{"Calcaires kimméridgiens à exogyra virgula"}', '26 ha. Le plus grand et souvent considéré comme le plus complet des 7 climats du Chablis Grand Cru. Profondeur minérale, longue garde. Raveneau, Dauvissat, William Fèvre, Christian Moreau (Clos des Hospices).', null, '5', '5', null, '{"iconique","chablis","grand-cru"}', 'lpv|inao'), ('bourgogne-terr-gc-chablis-les-preuses', 'bgn-gc-chablis-les-preuses', 'Chablis Grand Cru Les Preuses', 'climat', null, 'France', 'Bourgogne', 'Chablis', '{"Chardonnay"}', '180', '220', '{"Calcaires kimméridgiens"}', '11,4 ha. Souvent le plus séduisant et accessible jeune des grands crus chablisiens. Dauvissat, Fèvre, Drouhin, Louis Michel.', null, '5', '5', null, '{"chablis","grand-cru","accessible"}', 'lpv|inao'), ('bourgogne-terr-gc-chablis-valmur', 'bgn-gc-chablis-valmur', 'Chablis Grand Cru Valmur', 'climat', null, 'France', 'Bourgogne', 'Chablis', '{"Chardonnay"}', '180', '220', '{"Calcaires kimméridgiens"}', '11,7 ha. Profondeur, structure tannique blanche, garde longue. Raveneau, Christian Moreau.', null, '5', '5', null, '{"chablis","grand-cru"}', 'lpv|inao'), ('bourgogne-terr-gc-chablis-vaudesir', 'bgn-gc-chablis-vaudesir', 'Chablis Grand Cru Vaudésir', 'climat', null, 'France', 'Bourgogne', 'Chablis', '{"Chardonnay"}', '180', '220', '{"Calcaires kimméridgiens"}', '16,2 ha. Le plus aérien et floral des grands crus de Chablis. Drouhin, Louis Michel, Fèvre, Moreau.', null, '5', '5', null, '{"chablis","grand-cru","finesse"}', 'lpv|inao'), ('bourgogne-terr-gc-chambertin', 'bgn-gc-chambertin', 'Chambertin', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '275', '300', '{"Calcaires bajociens, sols caillouteux et argileux"}', '12,9 ha. Le « roi des vins » selon Napoléon. Puissance, garde, structure. Rousseau, Trapet, Ponsot, Charlopin, Mortet, Leroy, Drouhin.', null, '5', '5', null, '{"iconique","gevrey","puissance"}', 'lpv|inao'), ('bourgogne-terr-gc-clos-beze', 'bgn-gc-clos-beze', 'Chambertin-Clos de Bèze', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '275', '300', '{"Calcaires bajociens, sols caillouteux et argileux"}', '15,4 ha. Jumeau historique de Chambertin (peut être étiqueté « Chambertin »). Souvent un poil plus aérien. Rousseau, Faiveley, Drouhin-Laroze, Bart, Bruno Clair.', null, '5', '5', null, '{"iconique","gevrey"}', 'lpv|inao'), ('bourgogne-terr-1c-amoureuses', 'bgn-1c-amoureuses', 'Chambolle-Musigny 1er Cru Les Amoureuses', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '280', '{"Calcaires bajociens, sols superficiels"}', '5,4 ha. Le 1er cru le plus mythique de Bourgogne, souvent considéré comme un grand cru de fait. Style aérien, parfumé. Roumier, Mugnier, de Vogüé, Groffier, Amiot-Servelle, Drouhin.', null, '5', '5', null, '{"iconique","chambolle","grand-cru-de-fait"}', 'lpv|inao'), ('bourgogne-terr-1c-caillerets-chassagne', 'bgn-1c-caillerets-chassagne', 'Chassagne-Montrachet 1er Cru Les Caillerets', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '240', '280', '{"Calcaires bathoniens"}', '14,4 ha. Le 1er cru le plus prestigieux de Chassagne, voisin de Montrachet. Ramonet, Pillot, Bachelet-Ramonet, Marc Colin.', null, '5', '5', null, '{"chassagne","grand-cru-de-fait"}', 'lpv|inao'), ('bourgogne-terr-gc-chevalier-montrachet', 'bgn-gc-chevalier-montrachet', 'Chevalier-Montrachet', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '260', '280', '{"Calcaires fins, sols superficiels"}', '7,4 ha. Plus haut, plus pauvre que Le Montrachet. Style plus tendu et minéral, parfois plus austère. Leflaive, Bouchard (La Cabotte), Niellon, Latour, Sauzet, d''Auvenay.', null, '5', '5', null, '{"iconique","puligny","chardonnay","minerale"}', 'lpv|inao'), ('bourgogne-terr-gc-clos-tart', 'bgn-gc-clos-tart', 'Clos de Tart', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '270', '300', '{"Calcaires de Comblanchien, sols caillouteux"}', '7,5 ha de monopole intégral. Domaine du Clos de Tart (Artémis). L''un des très rares grands crus en monopole. Style ciselé.', null, '5', '5', null, '{"iconique","monopole","morey","artemis"}', 'lpv|inao'), ('bourgogne-terr-gc-clos-saint-denis', 'bgn-gc-clos-saint-denis', 'Clos Saint-Denis', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '240', '270', '{"Calcaires bajociens et alluvions"}', '6,6 ha. Plus aérien et fin que Clos de la Roche. Dujac, Amiot, Ponsot, Charlopin.', null, '5', '5', null, '{"morey","finesse"}', 'lpv|inao'), ('bourgogne-terr-gc-corton-charlemagne', 'bgn-gc-corton-charlemagne', 'Corton-Charlemagne', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '270', '330', '{"Marnes blanches, calcaires bathoniens"}', '52 ha. Le grand cru blanc le plus puissant de Bourgogne. Plus minéral et long que Corton blanc. Coche-Dury, Bonneau du Martray, Bouchard, Rapet, Leroy.', null, '5', '5', null, '{"iconique","aloxe","chardonnay","puissance"}', 'lpv|inao'), ('bourgogne-terr-gc-criots-batard', 'bgn-gc-criots-batard', 'Criots-Bâtard-Montrachet', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '240', '260', '{"Marnes argileuses"}', '1,6 ha — le plus petit grand cru blanc de Bourgogne, intégralement à Chassagne. d''Auvenay, Belland, Fontaine-Gagnard, Hubert Lamy.', null, '5', '5', null, '{"chassagne","chardonnay","rare"}', 'lpv|inao'), ('bourgogne-terr-1c-clos-saint-jacques', 'bgn-1c-clos-saint-jacques', 'Gevrey-Chambertin 1er Cru Clos Saint-Jacques', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '275', '300', '{"Calcaires bajociens, sols caillouteux"}', '6,7 ha. Considéré par beaucoup comme un grand cru de fait. Cinq propriétaires uniquement (Rousseau, Fourrier, Bruno Clair, Esmonin, Jadot). Style ample, profond, garde longue.', null, '5', '5', null, '{"iconique","gevrey","grand-cru-de-fait"}', 'lpv|inao'), ('bourgogne-terr-gc-grands-echezeaux', 'bgn-gc-grands-echezeaux', 'Grands Échezeaux', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '275', '{"Calcaires bajociens, sols argilo-calcaires"}', '9,1 ha. Plus structuré et plus profond qu''Échezeaux, parfois proche de Clos de Vougeot dans le caractère. Garde longue.', null, '5', '5', null, '{"vosne","grand-cru"}', 'lpv|inao'), ('bourgogne-terr-gc-griotte-chambertin', 'bgn-gc-griotte-chambertin', 'Griotte-Chambertin', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '275', '285', '{"Calcaires bajociens"}', '2,7 ha — l''un des plus petits grands crus de Gevrey. Notes de griotte (cerise) caractéristiques. Drouhin, Fourrier, Duroché.', null, '5', '5', null, '{"gevrey","fruite","finesse"}', 'lpv|inao'), ('bourgogne-terr-gc-la-romanee', 'bgn-gc-la-romanee', 'La Romanée', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '270', '285', '{"Calcaires bajociens, sols caillouteux"}', '0,84 ha — la plus petite AOC de France. Monopole du Comte Liger-Belair. Style très tendu, minéral, qui demande de la garde.', null, '5', '5', null, '{"iconique","monopole","liger-belair","vosne"}', 'lpv|inao'), ('bourgogne-terr-gc-la-tache', 'bgn-gc-la-tache', 'La Tâche', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '300', '{"Calcaires et marnes"}', '6,06 ha de monopole DRC. Souvent considéré comme le « petit frère » de la Romanée-Conti, parfois plus immédiatement séduisant. Notes de violette et d''épices.', null, '5', '5', null, '{"iconique","monopole","drc","vosne"}', 'lpv|inao'), ('bourgogne-terr-gc-latricieres-chambertin', 'bgn-gc-latricieres-chambertin', 'Latricières-Chambertin', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '275', '300', '{"Calcaires bajociens"}', '7,4 ha. Voisin direct de Chambertin, mais sols plus pauvres et caillouteux. Style minéral, tendu, garde longue. Rossignol-Trapet, Faiveley, Camus, Duroché.', null, '5', '5', null, '{"gevrey","minerale"}', 'lpv|inao'), ('bourgogne-terr-gc-le-montrachet', 'bgn-gc-le-montrachet', 'Le Montrachet', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '250', '265', '{"Marnes calcaires, sols caillouteux exposés est-sud-est"}', '8 ha. Le grand cru blanc le plus mythique du monde. Profondeur, complexité, longévité. DRC (0,68 ha), Comtes Lafon, Leroy, Bouchard, Drouhin (Marquis de Laguiche), Ramonet.', null, '5', '5', null, '{"iconique","puligny","chassagne","chardonnay"}', 'lpv|inao'), ('bourgogne-terr-gc-mazis-chambertin', 'bgn-gc-mazis-chambertin', 'Mazis-Chambertin', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '275', '300', '{"Calcaires bajociens"}', '9,1 ha. Le plus puissant des « satellites » de Chambertin. Mazis-Hauts plus fin que Mazis-Bas. Rousseau, Hospices (Madeleine Collignon), Faiveley, Charlopin, d''Auvenay.', null, '5', '5', null, '{"gevrey","puissance"}', 'lpv|inao'), ('bourgogne-terr-1c-perrieres-meursault', 'bgn-1c-perrieres-meursault', 'Meursault 1er Cru Les Perrières', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '260', '290', '{"Calcaires durs, sols caillouteux"}', '13,7 ha. Le plus minéral des 1ers crus de Meursault, candidat de longue date au grand cru. Coche-Dury, Roulot, Lafon, Pierre Morey, Sauzet.', null, '5', '5', null, '{"meursault","grand-cru-de-fait","minerale"}', 'lpv|inao'), ('bourgogne-terr-gc-musigny', 'bgn-gc-musigny', 'Musigny', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir","Chardonnay"}', '260', '300', '{"Calcaires et marnes blanches"}', '10,9 ha. Grand cru de Chambolle, l''un des plus fins de Bourgogne. Vogüé en propriétaire dominant (7 ha). Petite production de blanc (Vogüé).', null, '5', '5', null, '{"iconique","chambolle","finesse"}', 'lpv|inao'), ('bourgogne-terr-1c-saint-georges', 'bgn-1c-saint-georges', 'Nuits-Saint-Georges 1er Cru Les Saint-Georges', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '280', '{"Calcaires bajociens"}', '7,5 ha. Le climat phare de Nuits, candidat de longue date au grand cru. Style profond, garde longue. Chevillon, Faiveley, Gouges, Thibault Liger-Belair.', null, '5', '5', null, '{"nuits-saint-georges","grand-cru-de-fait"}', 'lpv|inao'), ('bourgogne-terr-1c-rugiens', 'bgn-1c-rugiens', 'Pommard 1er Cru Les Rugiens', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Pinot Noir"}', '260', '300', '{"Calcaires et marnes rouges (« rugines »)"}', '12,7 ha (Rugiens-Hauts + Rugiens-Bas). Candidat de longue date au grand cru. Rugiens-Bas considéré comme le meilleur. de Montille, Comte Armand, Hospices.', null, '5', '5', null, '{"pommard","grand-cru-de-fait"}', 'lpv|inao'), ('bourgogne-terr-v-puligny-village', 'bgn-v-puligny-village', 'Puligny-Montrachet', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '230', '280', '{"Calcaires bathoniens"}', '207 ha. 17 1ers crus + 4 grands crus. Référence absolue du Chardonnay minéral et tendu. Style ciselé, salin.', null, '5', '5', null, '{"puligny","appellation","minerale"}', 'lpv|inao'), ('bourgogne-terr-1c-pucelles', 'bgn-1c-pucelles', 'Puligny-Montrachet 1er Cru Les Pucelles', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '240', '260', '{"Calcaires bathoniens"}', '6,8 ha. Voisin direct des Bâtard. Style très puligny : minéralité, tension, finesse. Leflaive, Carillon, Boyer-Martenot, Paul Pernot.', null, '5', '5', null, '{"puligny","premier-cru","grand-cru-de-fait"}', 'lpv|inao'), ('bourgogne-terr-gc-richebourg', 'bgn-gc-richebourg', 'Richebourg', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '280', '{"Calcaires bajociens, sols rouges argilo-calcaires"}', '8 ha. Le plus puissant des grands crus de Vosne. Profondeur tannique, plénitude, longue garde. DRC, Leroy, Méo-Camuzet, Anne Gros, Liger-Belair, Hudelot-Noëllat, Grivot, Gros Frère.', null, '5', '5', null, '{"iconique","vosne","puissance"}', 'lpv|inao'), ('bourgogne-terr-gc-romanee-conti', 'bgn-gc-romanee-conti', 'Romanée-Conti', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '275', '{"Calcaires bajociens et bathoniens, marnes"}', '1,8 ha de monopole DRC. Le climat le plus mythique du monde du vin. Profondeur, pureté aromatique, longévité quasi infinie.', null, '5', '5', null, '{"iconique","monopole","drc","vosne"}', 'lpv|inao|drc.eu'), ('bourgogne-terr-gc-romanee-saint-vivant', 'bgn-gc-romanee-saint-vivant', 'Romanée-Saint-Vivant', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '275', '{"Calcaires bajociens et marnes profondes"}', '9,4 ha. Le plus aérien des grands crus de Vosne. Finesse florale, structure soyeuse. DRC (5,3 ha), Leroy, Cathiard, Hudelot-Noëllat, Arnoux-Lachaux, Liger-Belair, Poisot.', null, '5', '5', null, '{"iconique","vosne","finesse"}', 'lpv|inao'), ('bourgogne-terr-gc-ruchottes-chambertin', 'bgn-gc-ruchottes-chambertin', 'Ruchottes-Chambertin', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '300', '320', '{"Calcaires bathoniens, sols rocailleux"}', '3,3 ha. Le plus haut grand cru de Gevrey, le plus minéral. Style tendu, minéralité crayeuse. Rousseau, Roumier, Marchand-Tawse.', null, '5', '5', null, '{"gevrey","minerale","altitude"}', 'lpv|inao'), ('bourgogne-terr-1c-caillerets-volnay', 'bgn-1c-caillerets-volnay', 'Volnay 1er Cru Les Caillerets', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Pinot Noir"}', '260', '290', '{"Calcaires bathoniens"}', '14,3 ha. Le climat le plus prestigieux de Volnay, candidat au grand cru. Lafarge, d''Angerville, Bouchard, Pousse d''Or.', null, '5', '5', null, '{"volnay","grand-cru-de-fait"}', 'lpv|inao'), ('bourgogne-terr-v-vosne-village', 'bgn-v-vosne-village', 'Vosne-Romanée', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '240', '300', '{"Calcaires bajociens, sols caillouteux"}', '159 ha. 14 1ers crus + 8 grands crus. La référence absolue du Pinot Noir au monde. Style profond, complexe, aromatique.', null, '5', '5', null, '{"iconique","vosne","appellation"}', 'lpv|inao'), ('bourgogne-terr-1c-malconsorts', 'bgn-1c-malconsorts', 'Vosne-Romanée 1er Cru Aux Malconsorts', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '275', '{"Calcaires bajociens"}', '5,9 ha. Voisin direct de La Tâche. Souvent considéré comme un grand cru de fait. Cathiard, de Montille, Hudelot-Noëllat, Lamarche.', null, '5', '5', null, '{"vosne","grand-cru-de-fait"}', 'lpv|inao'), ('bourgogne-terr-1c-cros-parantoux', 'bgn-1c-cros-parantoux', 'Vosne-Romanée 1er Cru Cros Parantoux', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '275', '{"Calcaires bajociens, sols rocailleux"}', '1,01 ha. Climat ressuscité par Henri Jayer (qui en avait 0,72 ha). Désormais Méo-Camuzet (0,72 ha) et Emmanuel Rouget (0,29 ha). Vins légendaires, prix d''un GC.', null, '5', '5', null, '{"iconique","vosne","jayer","grand-cru-de-fait"}', 'lpv|inao'), ('bourgogne-terr-gc-bonnes-mares', 'bgn-gc-bonnes-mares', 'Bonnes-Mares', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '300', '{"Calcaires bajociens (Chambolle), marnes et calcaires blancs (Morey)"}', '15,1 ha à cheval sur Chambolle et Morey. Plus structuré que Musigny, plus puissant. Vogüé, Roumier, Drouhin-Laroze, de Vogüé, Bart, Groffier.', null, '5', '4', null, '{"iconique","chambolle","morey"}', 'lpv|inao'), ('bourgogne-terr-1c-clos-mouches', 'bgn-1c-clos-mouches', 'Beaune 1er Cru Clos des Mouches', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Pinot Noir","Chardonnay"}', '240', '260', '{"Calcaires bathoniens, sols caillouteux"}', '25,4 ha. Climat phare de Beaune, signature historique de Drouhin (production de référence en blanc et rouge). Aussi Jadot, Chanson.', null, '4', '4', null, '{"beaune","premier-cru","drouhin"}', 'lpv|inao'), ('bourgogne-terr-1c-greves', 'bgn-1c-greves', 'Beaune 1er Cru Les Grèves', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Pinot Noir"}', '240', '280', '{"Calcaires et alluvions, sols caillouteux"}', '31,3 ha. Le plus grand 1er cru de Beaune. Bouchard (Vigne de l''Enfant Jésus), Jadot, Camille Giroud, Tollot-Beaut.', null, '4', '4', null, '{"beaune","premier-cru"}', 'lpv|inao'), ('bourgogne-terr-1c-vaillons', 'bgn-1c-vaillons', 'Chablis 1er Cru Vaillons', 'premier_cru', null, 'France', 'Bourgogne', 'Chablis', '{"Chardonnay"}', '180', '220', '{"Calcaires kimméridgiens"}', '210 ha (incl. lieux-dits). Plus à l''ouest, exposition est, style un poil plus aérien. Raveneau, Dauvissat, Servin, Tribut.', null, '4', '4', null, '{"chablis","premier-cru"}', 'lpv|inao'), ('bourgogne-terr-gc-chablis-blanchot', 'bgn-gc-chablis-blanchot', 'Chablis Grand Cru Blanchot', 'climat', null, 'France', 'Bourgogne', 'Chablis', '{"Chardonnay"}', '180', '220', '{"Calcaires kimméridgiens"}', '12,7 ha. Plus à l''est, exposition plus chaude. Style ample, parfois plus mûr que les autres. Raveneau, Fèvre, Servin.', null, '4', '4', null, '{"chablis","grand-cru"}', 'lpv|inao'), ('bourgogne-terr-gc-chablis-bougros', 'bgn-gc-chablis-bougros', 'Chablis Grand Cru Bougros', 'climat', null, 'France', 'Bourgogne', 'Chablis', '{"Chardonnay"}', '180', '220', '{"Calcaires kimméridgiens"}', '12,6 ha. Le plus à l''ouest, parcelles parfois en pente raide. Côte Bouguerots (Fèvre) parmi les meilleures expressions.', null, '4', '4', null, '{"chablis","grand-cru"}', 'lpv|inao'), ('bourgogne-terr-gc-chablis-grenouilles', 'bgn-gc-chablis-grenouilles', 'Chablis Grand Cru Grenouilles', 'climat', null, 'France', 'Bourgogne', 'Chablis', '{"Chardonnay"}', '180', '220', '{"Calcaires kimméridgiens"}', '9,4 ha. Climat majoritairement détenu par La Chablisienne (cave coopérative, Château Grenouilles). Style salin et tendu.', null, '4', '4', null, '{"chablis","grand-cru"}', 'lpv|inao'), ('bourgogne-terr-v-chambolle-village', 'bgn-v-chambolle-village', 'Chambolle-Musigny', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '240', '330', '{"Calcaires bajociens, sols superficiels"}', '152 ha. 24 1ers crus + 2 grands crus (Musigny, Bonnes-Mares). Référence absolue de la finesse en Bourgogne. Style aérien, parfumé, féminin.', null, '4', '4', null, '{"chambolle","appellation","finesse"}', 'lpv|inao'), ('bourgogne-terr-1c-charmes-chambolle', 'bgn-1c-charmes-chambolle', 'Chambolle-Musigny 1er Cru Les Charmes', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '280', '{"Calcaires bajociens"}', '9 ha. Plus charnu et accessible jeune que Les Amoureuses. Roumier, Amiot-Servelle, Hudelot-Baillet.', null, '4', '4', null, '{"chambolle","premier-cru"}', 'lpv|inao'), ('bourgogne-terr-gc-chapelle-chambertin', 'bgn-gc-chapelle-chambertin', 'Chapelle-Chambertin', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '275', '285', '{"Calcaires bajociens"}', '5,4 ha. Plus aérien et floral que Chambertin. Trapet, Damoy, Drouhin-Laroze, Rossignol-Trapet.', null, '4', '4', null, '{"gevrey","floral"}', 'lpv|inao'), ('bourgogne-terr-gc-charmes-chambertin', 'bgn-gc-charmes-chambertin', 'Charmes-Chambertin', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '285', '{"Calcaires et alluvions, plus argileux que Chambertin"}', '30,8 ha (incl. Mazoyères). Le plus accessible des grands crus de Gevrey. Style charnu, fruité, garde plus courte. Bachelet, Roumier, Rousseau, Dujac, Magnien.', null, '4', '4', null, '{"gevrey","charnu","accessible"}', 'lpv|inao'), ('bourgogne-terr-v-chassagne-village', 'bgn-v-chassagne-village', 'Chassagne-Montrachet', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay","Pinot Noir"}', '230', '330', '{"Calcaires bathoniens"}', '297 ha. 55 1ers crus (le plus grand nombre de la CdB) + 3 grands crus partagés avec Puligny. Production blanche dominante depuis 30 ans.', null, '4', '4', null, '{"chassagne","appellation"}', 'lpv|inao'), ('bourgogne-terr-gc-clos-vougeot', 'bgn-gc-clos-vougeot', 'Clos de Vougeot', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '240', '270', '{"Calcaires bajociens haut, marnes et alluvions bas"}', '50,6 ha. Plus grand grand cru de la CdN, partagé entre 80 propriétaires. Qualité très hétérogène : haut du clos > milieu > bas. Le « vrai » CdV est celui des hauteurs.', null, '4', '4', null, '{"vosne","grand-cru","heterogene"}', 'lpv|inao'), ('bourgogne-terr-gc-clos-lambrays', 'bgn-gc-clos-lambrays', 'Clos des Lambrays', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '270', '310', '{"Calcaires variés, sols caillouteux"}', '8,8 ha quasi-monopole du Domaine des Lambrays (LVMH). Promu grand cru tardif (1981). Style aérien, parfumé.', null, '4', '4', null, '{"morey","monopole","lvmh"}', 'lpv|inao'), ('bourgogne-terr-gc-corton', 'bgn-gc-corton', 'Corton', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Pinot Noir","Chardonnay"}', '270', '330', '{"Marnes rouges (haut), calcaires bathoniens (milieu), oolithes (bas)"}', '94 ha. Seul grand cru rouge de la Côte de Beaune. Climats hétérogènes (Bressandes, Renardes, Clos du Roi, Pougets, Maréchaudes, etc.). Quelques % en blanc. Bonneau du Martray, Tollot-Beaut, Faiveley, Chandon de Briailles, Rapet.', null, '4', '4', null, '{"iconique","aloxe","grand-cru","heterogene"}', 'lpv|inao'), ('bourgogne-terr-1c-lavaut-saint-jacques', 'bgn-1c-lavaut-saint-jacques', 'Gevrey-Chambertin 1er Cru Lavaut Saint-Jacques', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '270', '300', '{"Calcaires bajociens"}', '9,5 ha. Voisin direct du Clos Saint-Jacques. Style un poil plus minéral. Trapet, Mortet, Duroché, Esmonin.', null, '4', '4', null, '{"gevrey","premier-cru"}', 'lpv|inao'), ('bourgogne-terr-1c-cazetiers', 'bgn-1c-cazetiers', 'Gevrey-Chambertin 1er Cru Les Cazetiers', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '270', '300', '{"Calcaires bajociens"}', '8,3 ha. Climat tendu et minéral, l''un des meilleurs 1ers crus de Gevrey. Bruno Clair, Faiveley, Rousseau (parcelle).', null, '4', '4', null, '{"gevrey","premier-cru","minerale"}', 'lpv|inao'), ('bourgogne-terr-gc-la-grande-rue', 'bgn-gc-la-grande-rue', 'La Grande Rue', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '280', '{"Calcaires bajociens"}', '1,65 ha. Monopole du Domaine François Lamarche. Promu en grand cru en 1992 (auparavant 1er cru). Encadré par La Tâche et Romanée-Conti.', null, '4', '4', null, '{"monopole","lamarche","vosne"}', 'lpv|inao'), ('bourgogne-terr-gc-mazoyeres-chambertin', 'bgn-gc-mazoyeres-chambertin', 'Mazoyères-Chambertin', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '285', '{"Argilo-calcaires, plus argileux que Chambertin"}', 'Inclus dans Charmes-Chambertin (peut s''appeler Charmes ou Mazoyères). Rare en étiquette dédiée. Perrot-Minot, Magnien.', null, '4', '4', null, '{"gevrey"}', 'lpv|inao'), ('bourgogne-terr-1c-charmes-meursault', 'bgn-1c-charmes-meursault', 'Meursault 1er Cru Charmes', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '240', '260', '{"Calcaires bathoniens, sols profonds"}', '31,1 ha. Le plus grand 1er cru de Meursault. Style charnu et beurré, plus accessible jeune que Perrières. Lafon, Roulot, Bouchard.', null, '4', '4', null, '{"meursault","premier-cru","charnu"}', 'lpv|inao'), ('bourgogne-terr-1c-genevrieres', 'bgn-1c-genevrieres', 'Meursault 1er Cru Genevrières', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '260', '280', '{"Calcaires bathoniens"}', '16,5 ha. Style intermédiaire entre Charmes et Perrières. Lafon, Bouchard, Faiveley, Pierre Morey.', null, '4', '4', null, '{"meursault","premier-cru"}', 'lpv|inao'), ('bourgogne-terr-v-nuits-village', 'bgn-v-nuits-village', 'Nuits-Saint-Georges', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir","Chardonnay"}', '230', '330', '{"Calcaires bajociens, alluvions"}', '307 ha. 41 1ers crus, aucun grand cru (anomalie historique). Style structuré, garde longue, plus austère que Vosne. Les Saint-Georges en candidat au grand cru.', null, '4', '4', null, '{"nuits-saint-georges","appellation"}', 'lpv|inao'), ('bourgogne-terr-1c-vaucrains', 'bgn-1c-vaucrains', 'Nuits-Saint-Georges 1er Cru Les Vaucrains', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '280', '{"Calcaires bajociens"}', '6,2 ha. Voisin direct des Saint-Georges. Style un poil plus austère et tannique. Chevillon, Gouges, Cathiard.', null, '4', '4', null, '{"nuits-saint-georges","premier-cru"}', 'lpv|inao'), ('bourgogne-terr-1c-epenots', 'bgn-1c-epenots', 'Pommard 1er Cru Les Épenots', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Pinot Noir"}', '260', '280', '{"Calcaires bathoniens"}', '16,2 ha (Grands + Petits). Style un poil plus aérien que Rugiens. Comte Armand (Clos des Épeneaux, monopole), de Courcel, Aleth Le Royer-Girardin.', null, '4', '4', null, '{"pommard","premier-cru"}', 'lpv|inao'), ('bourgogne-terr-v-pouilly-fuisse', 'bgn-v-pouilly-fuisse', 'Pouilly-Fuissé', 'appellation_village', null, 'France', 'Bourgogne', 'Mâconnais', '{"Chardonnay"}', '200', '450', '{"Calcaires bajociens, marnes"}', '800 ha sur les communes de Vergisson, Solutré-Pouilly, Fuissé, Chaintré. 22 1ers crus depuis 2020 (première fois en Mâconnais). Style ample, minéral, montée en gamme nette. Guffens, Merlin, Ferret, Robert-Denogent.', null, '4', '4', null, '{"maconnais","premier-cru-recent","montee-gamme"}', 'lpv|inao'), ('bourgogne-terr-1c-combettes', 'bgn-1c-combettes', 'Puligny-Montrachet 1er Cru Les Combettes', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '240', '260', '{"Calcaires bathoniens"}', '6,8 ha. Voisin de Charmes (Meursault). Style charnu pour un Puligny, plus mûr. Leflaive, Sauzet, Carillon.', null, '4', '4', null, '{"puligny","premier-cru"}', 'lpv|inao'), ('bourgogne-terr-1c-folatieres', 'bgn-1c-folatieres', 'Puligny-Montrachet 1er Cru Les Folatières', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '260', '300', '{"Calcaires bathoniens, sols caillouteux"}', '17,6 ha. Le plus haut 1er cru de Puligny. Style minéral et tendu, parfois plus austère. Leflaive, Drouhin, Sauzet, Lambrays.', null, '4', '4', null, '{"puligny","premier-cru","altitude"}', 'lpv|inao'), ('bourgogne-terr-v-saint-aubin-village', 'bgn-v-saint-aubin-village', 'Saint-Aubin', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay","Pinot Noir"}', '270', '380', '{"Calcaires variés"}', '159 ha. 20 1ers crus dont En Remilly et Sous Roche Dumay. Voisin de Montrachet. Excellent rapport qualité-prix sur les blancs. Style ciselé.', null, '4', '4', null, '{"saint-aubin","qualite-prix"}', 'lpv|inao'), ('bourgogne-terr-1c-en-remilly', 'bgn-1c-en-remilly', 'Saint-Aubin 1er Cru En Remilly', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '300', '320', '{"Calcaires bathoniens, sols caillouteux"}', '10,9 ha. Voisin direct de Le Montrachet. Le 1er cru le plus prestigieux de Saint-Aubin. PYC Morey, Marc Colin, Hubert Lamy, Dujac.', null, '4', '4', null, '{"saint-aubin","premier-cru","altitude"}', 'lpv|inao'), ('bourgogne-terr-v-volnay-village', 'bgn-v-volnay-village', 'Volnay', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Pinot Noir"}', '230', '330', '{"Calcaires bathoniens, marnes"}', '215 ha. 29 1ers crus, aucun grand cru. Référence absolue du Pinot fin et aérien en Côte de Beaune. d''Angerville, Lafarge, de Montille, Comte Armand.', null, '4', '4', null, '{"volnay","appellation","finesse"}', 'lpv|inao'), ('bourgogne-terr-1c-clos-chenes', 'bgn-1c-clos-chenes', 'Volnay 1er Cru Clos des Chênes', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Pinot Noir"}', '260', '300', '{"Calcaires bathoniens"}', '16 ha. Voisin de Caillerets. Style un poil plus structuré. Lafarge, de Montille, Comte Armand, Lafouge.', null, '4', '4', null, '{"volnay","premier-cru"}', 'lpv|inao'), ('bourgogne-terr-1c-clos-ducs', 'bgn-1c-clos-ducs', 'Volnay 1er Cru Clos des Ducs', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Pinot Noir"}', '270', '285', '{"Calcaires bathoniens"}', '2,1 ha de monopole d''Angerville. Style très volnaysien : finesse, élégance, longue garde.', null, '4', '4', null, '{"volnay","monopole","angerville"}', 'lpv|inao'), ('bourgogne-terr-1c-beaumonts', 'bgn-1c-beaumonts', 'Vosne-Romanée 1er Cru Les Beaumonts', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '285', '{"Calcaires bajociens"}', '11 ha. Style structuré et profond. Grivot, Hudelot-Noëllat, Clavelier, Cathiard, Arnoux-Lachaux.', null, '4', '4', null, '{"vosne","premier-cru","profondeur"}', 'lpv|inao'), ('bourgogne-terr-1c-suchots', 'bgn-1c-suchots', 'Vosne-Romanée 1er Cru Les Suchots', 'premier_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '260', '275', '{"Calcaires bajociens"}', '13,1 ha. Le plus grand 1er cru de Vosne. Voisin de Romanée-Saint-Vivant. Style charnu, généreux. Cathiard, Arnoux-Lachaux, Confuron-Cotetidot, Hudelot-Noëllat.', null, '4', '4', null, '{"vosne","premier-cru"}', 'lpv|inao'), ('bourgogne-terr-gc-echezeaux', 'bgn-gc-echezeaux', 'Échezeaux', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '240', '300', '{"Calcaires variés, lieux-dits hétérogènes"}', '37,7 ha — l''un des plus grands « grands crus » de Bourgogne, ce qui explique sa qualité variable. 11 lieux-dits (Les Rouges du Bas, Champs Traversins, Quartiers de Nuits, etc.).', null, '4', '4', null, '{"vosne","grand-cru","heterogene"}', 'lpv|inao'), ('bourgogne-terr-v-bouzeron', 'bgn-v-bouzeron', 'Bouzeron', 'appellation_village', null, 'France', 'Bourgogne', 'Côte Chalonnaise', '{"Aligoté Doré"}', '230', '330', '{"Calcaires variés, marnes"}', '55 ha. Seule appellation village de Bourgogne en Aligoté (variante Aligoté Doré). Référence : Aubert de Villaine. Style ample, minéral, qui prend de l''âge.', null, '3', '4', null, '{"bouzeron","aligote","monocepage"}', 'lpv|inao'), ('bourgogne-terr-gc-charlemagne', 'bgn-gc-charlemagne', 'Charlemagne', 'grand_cru', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay"}', '270', '330', '{"Marnes blanches, calcaires bathoniens"}', 'Climat plus restreint (et moins utilisé) inclus dans la zone Corton-Charlemagne. Étiquette quasi-disparue.', null, '3', '4', null, '{"aloxe","chardonnay","rare"}', 'lpv|inao'), ('bourgogne-terr-v-givry', 'bgn-v-givry', 'Givry', 'appellation_village', null, 'France', 'Bourgogne', 'Côte Chalonnaise', '{"Pinot Noir","Chardonnay"}', '240', '330', '{"Calcaires variés, marnes"}', '270 ha. 38 1ers crus. Production rouge dominante. Style accessible, gourmand. Joblot, Lumpp, Ragot, Chofflet-Valdenaire.', null, '3', '4', null, '{"givry","qualite-prix"}', 'lpv|inao'), ('bourgogne-terr-v-pouilly-vinzelles', 'bgn-v-pouilly-vinzelles', 'Pouilly-Vinzelles', 'appellation_village', null, 'France', 'Bourgogne', 'Mâconnais', '{"Chardonnay"}', '200', '300', '{"Calcaires variés"}', '53 ha. Petite appellation, plus simple que Pouilly-Fuissé. Bret Brothers (La Soufrandière) référence absolue.', null, '3', '4', null, '{"maconnais","qualite-prix"}', 'lpv|inao'), ('bourgogne-terr-v-rully', 'bgn-v-rully', 'Rully', 'appellation_village', null, 'France', 'Bourgogne', 'Côte Chalonnaise', '{"Chardonnay","Pinot Noir"}', '230', '330', '{"Calcaires variés, marnes"}', '330 ha. 23 1ers crus. Production majoritairement en blanc. Style ciselé, bon rapport qualité-prix. Dureuil-Janthial, Jacqueson, Briday.', null, '3', '4', null, '{"rully","qualite-prix"}', 'lpv|inao'), ('bourgogne-terr-v-saint-bris', 'bgn-v-saint-bris', 'Saint-Bris', 'appellation_village', null, 'France', 'Bourgogne', 'Auxerrois', '{"Sauvignon Blanc"}', '150', '280', '{"Calcaires kimméridgiens"}', '133 ha. Unique appellation Sauvignon Blanc de Bourgogne (anomalie historique). Style minéral, tendu. Goisot référence.', null, '3', '4', null, '{"saint-bris","sauvignon","auxerrois"}', 'lpv|inao'), ('bourgogne-terr-v-saint-veran', 'bgn-v-saint-veran', 'Saint-Véran', 'appellation_village', null, 'France', 'Bourgogne', 'Mâconnais', '{"Chardonnay"}', '200', '380', '{"Calcaires variés, schistes"}', '750 ha. Encadre Pouilly-Fuissé. Style frais, accessible, excellent rapport qualité-prix. Merlin, Saumaize-Michelin, Barraud.', null, '3', '4', null, '{"maconnais","qualite-prix"}', 'lpv|inao'), ('bourgogne-terr-v-vire-clesse', 'bgn-v-vire-clesse', 'Viré-Clessé', 'appellation_village', null, 'France', 'Bourgogne', 'Mâconnais', '{"Chardonnay"}', '200', '330', '{"Calcaires variés, marnes"}', '390 ha. Connue pour les vendanges tardives (Bongran, Lévrier). Style mûr, parfois moelleux selon le millésime. Thévenet/Bongran référence.', null, '3', '4', null, '{"maconnais","vendanges-tardives"}', 'lpv|inao'), ('bourgogne-terr-v-chablis-village', 'bgn-v-chablis-village', 'Chablis', 'appellation_village', null, 'France', 'Bourgogne', 'Chablis', '{"Chardonnay"}', '150', '220', '{"Calcaires kimméridgiens à exogyra virgula"}', '3 200 ha (incluant 1ers et grands crus). Le Chardonnay le plus minéral du monde. Style salin, tranchant, peu de bois. Référence absolue.', null, '4', '3', null, '{"chablis","appellation","minerale"}', 'lpv|inao'), ('bourgogne-terr-v-gevrey-village', 'bgn-v-gevrey-village', 'Gevrey-Chambertin', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir"}', '230', '330', '{"Calcaires bajociens, marnes"}', 'Plus grande appellation village de la CdN (411 ha). 26 1ers crus + 9 grands crus. Profondeur, garde, structure, signature de style.', null, '4', '3', null, '{"gevrey","appellation"}', 'lpv|inao'), ('bourgogne-terr-v-meursault-village', 'bgn-v-meursault-village', 'Meursault', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Chardonnay","Pinot Noir"}', '230', '330', '{"Calcaires bathoniens"}', '412 ha. 19 1ers crus, aucun grand cru. Style ample, gras, beurré, signature Meursault. Référence absolue du Chardonnay charnu.', null, '4', '3', null, '{"meursault","appellation"}', 'lpv|inao'), ('bourgogne-terr-v-morey-village', 'bgn-v-morey-village', 'Morey-Saint-Denis', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir","Chardonnay"}', '230', '330', '{"Calcaires bajociens et bathoniens"}', '96 ha. 5 grands crus + 20 1ers crus. Souvent décrit comme un mélange entre la puissance de Gevrey et la finesse de Chambolle.', null, '4', '3', null, '{"morey","appellation"}', 'lpv|inao'), ('bourgogne-terr-v-aloxe-corton', 'bgn-v-aloxe-corton', 'Aloxe-Corton', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Pinot Noir","Chardonnay"}', '240', '330', '{"Marnes rouges, calcaires bathoniens"}', '94 ha. 14 1ers crus + grand cru Corton (en partie). Style charpenté, fruité.', null, '3', '3', null, '{"aloxe","appellation"}', 'lpv|inao'), ('bourgogne-terr-v-auxey-duresses', 'bgn-v-auxey-duresses', 'Auxey-Duresses', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Pinot Noir","Chardonnay"}', '270', '380', '{"Calcaires variés, sols caillouteux"}', '133 ha. 9 1ers crus. Vallée plus haute et plus fraîche, vins minéraux. Comte Armand, Lafouge, Roy, Coche-Dury (blancs).', null, '3', '3', null, '{"auxey","qualite-prix","fraicheur"}', 'lpv|inao'), ('bourgogne-terr-v-beaune-village', 'bgn-v-beaune-village', 'Beaune', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Beaune', '{"Pinot Noir","Chardonnay"}', '220', '330', '{"Calcaires bathoniens, alluvions"}', '411 ha. 42 1ers crus (le plus grand nombre de Bourgogne). Pas de grand cru. Style accessible, fruité, élégant. Bouchard, Drouhin, Jadot.', null, '3', '3', null, '{"beaune","appellation"}', 'lpv|inao'), ('bourgogne-terr-v-fixin', 'bgn-v-fixin', 'Fixin', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir","Chardonnay"}', '270', '330', '{"Calcaires bajociens"}', '100 ha. Souvent perçu comme le « petit Gevrey ». 6 1ers crus dont Clos de la Perrière. Bart, Berthaut-Gerbet, Pierre Gelin.', null, '3', '3', null, '{"fixin"}', 'lpv|inao'), ('bourgogne-terr-v-irancy', 'bgn-v-irancy', 'Irancy', 'appellation_village', null, 'France', 'Bourgogne', 'Auxerrois', '{"Pinot Noir","César"}', '150', '280', '{"Calcaires kimméridgiens"}', '160 ha. Seule appellation village rouge du Grand Auxerrois. Cépage Pinot Noir + accessoirement César (cépage local). Stéphanie Colinot, Goisot, Renaud.', null, '3', '3', null, '{"irancy","cesar","auxerrois"}', 'lpv|inao'), ('bourgogne-terr-v-marsannay', 'bgn-v-marsannay', 'Marsannay', 'appellation_village', null, 'France', 'Bourgogne', 'Côte de Nuits', '{"Pinot Noir","Chardonnay"}', '260', '330', '{"Calcaires bajociens et marnes"}', 'Seul village de la Côte d''Or à produire les 3 couleurs (rouge, blanc, rosé). 220 ha. Candidat à la promotion en 1er cru pour certains lieux-dits (Longeroies, Saint-Jacques). Bruno Clair, Bart, Audoin.', null, '3', '3', null, '{"marsannay","3-couleurs"}', 'lpv|inao'), ('bourgogne-terr-v-mercurey', 'bgn-v-mercurey', 'Mercurey', 'appellation_village', null, 'France', 'Bourgogne', 'Côte Chalonnaise', '{"Pinot Noir","Chardonnay"}', '240', '330', '{"Calcaires bajociens, marnes"}', '640 ha — la plus grande appellation village de Bourgogne en surface. 32 1ers crus. Production majoritairement en rouge. Style charpenté. Faiveley, Lorenzon, Juillot.', null, '3', '3', null, '{"mercurey","grande-appellation"}', 'lpv|inao'), ('bourgogne-terr-v-montagny', 'bgn-v-montagny', 'Montagny', 'appellation_village', null, 'France', 'Bourgogne', 'Côte Chalonnaise', '{"Chardonnay"}', '240', '380', '{"Calcaires variés"}', '326 ha. Uniquement en blanc. 49 1ers crus (anomalie historique : tout le village peut être 1er cru). Style frais, minéral. Berthenet, Stéphane Al