insert into regle_sommelier (id, type, portee, valeur, texte, actif, restaurant_id, priorite) values ('lola-r01', 'nombre_propositions', 'tout', '2', 'Deux propositions par plat.', 'true', 'lola', '1'), ('lola-r02', 'ton', 'tout', 'vouvoiement', 'Vouvoyer le client, pas de jargon technique dans les phrases courtes.', 'true', 'lola', '1'), ('lola-r03', 'mettre_en_avant', 'tout', 'coup_de_coeur', 'À note égale, préférer les coups de cœur de la carte.', 'false', 'lola', '1'), ('lola-r04', 'prix', 'tout', '50', 'Toujours au moins une proposition sous 50 €.', 'false', 'lola', '1'), ('lola-r05', 'service', 'tout', 'verre_d_abord', 'Quand un bon accord existe au verre, le proposer en premier.', 'false', 'lola', '1') on conflict (id) do update set type = excluded.type, portee = excluded.portee, valeur = excluded.valeur, texte = excluded.texte, actif = excluded.actif, restaurant_id = excluded.restaurant_id, priorite = excluded.priorite;
